#!/usr/bin/env python3
"""Render a captured hook log as a timeline: t+seconds, event, salient payload fields."""
import json
import sys

NOISE = {"transcript_path", "cwd", "session_id", "permission_mode", "workspace_dir"}

def brief(v, n=110):
    s = v if isinstance(v, str) else json.dumps(v)
    s = s.replace("\n", "\\n")
    return s if len(s) <= n else s[:n] + "…"

def main(path):
    recs = [json.loads(l) for l in open(path) if l.strip()]
    if not recs:
        print("(empty)")
        return
    t0 = recs[0]["t"]
    print(f"{'t+s':>8}  {'EVENT':<20} payload")
    print("-" * 100)
    for r in recs:
        p = r["payload"] or {}
        extra = {k: brief(v) for k, v in p.items()
                 if k not in NOISE and k != "hook_event_name"}
        hen = p.get("hook_event_name", "?")
        tag = r["declared_as"] if hen == r["declared_as"] else f"{r['declared_as']}(hen={hen})"
        print(f"{r['t']-t0:8.3f}  {tag:<20} {json.dumps(extra)[:400]}")
    print()
    print("=== distinct events fired ===")
    seen = {}
    for r in recs:
        seen.setdefault(r["declared_as"], 0)
        seen[r["declared_as"]] += 1
    for k, v in sorted(seen.items()):
        print(f"  {k}: {v}")
    print()
    print("=== full payload of first occurrence of each event ===")
    done = set()
    for r in recs:
        if r["declared_as"] in done:
            continue
        done.add(r["declared_as"])
        p = dict(r["payload"] or {})
        p.pop("transcript_path", None)
        p.pop("cwd", None)
        print(f"--- {r['declared_as']} ---")
        print(json.dumps(p, indent=2)[:2500])

if __name__ == "__main__":
    main(sys.argv[1])
